preToolUse.bash:
python3 -c "
import sys, json, re, os
try:
    args = json.loads(os.environ.get('COPILOT_TOOL_INPUT', '{}'))
except Exception:
    sys.exit(0)
path = args.get('path', args.get('file_path', args.get('filepath', '')))
if not path:
    sys.exit(0)
basename = os.path.basename(path)
patterns = [r'^\.env(\..+)?$', r'.*\.pem$', r'.*\.key$', r'.*\.p12$', r'^id_rsa$', r'^id_ed25519$', r'^id_dsa$', r'^id_ecdsa$']
for p in patterns:
    if re.match(p, basename):
        print(json.dumps({'permissionDecision': 'deny', 'permissionDecisionReason': f'Blocked: {basename} matches a sensitive file pattern. Ask the user to share it manually if needed.'}))
        sys.exit(0)
"
